export function FestiveReindeer() {
  return (
    <View style={{ width: 182, height: 168 }}>
      {pieces.map((piece) => (
        <View
          key={`${piece.x}-${piece.y}-${piece.width}`}
          style={{ position: "absolute", left: piece.x, top: piece.y }}
        >
          <SvgXml xml={piece.xml} width={piece.width} height={piece.height} />
        </View>
      ))}
    </View>
  );
}
